{
  "name": "builder_all_pairs_tie_dedup_001",
  "intuition": "All-pairs builder with explicit constraint handling: drop near-ties via a tie-zone and deduplicate symmetric/diagonal pairs while preserving pairwise PrefBatch output.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform_none",
    "constraint_family": "tie_zone_filter_and_dedup"
  },
  "operators_used": [
    "all_pairs",
    "tie_zone_filter",
    "dedup"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    hp = extra.get('hyperparams', {})\n\n    # Tie-zone filtering to avoid ambiguous/near-equal comparisons.\n    eps = float(hp.get('tie_eps', extra.get('tie_eps', 0.0)))\n\n    # Build all directed win/loss pairs then constrain.\n    # Use strict margin (objective_i + eps < objective_j) for lower-is-better.\n    win = (objective[:, :, None] + eps) < objective[:, None, :]\n\n    # Dedup: keep only upper-triangular pairs (i < j), which also removes diagonal.\n    n = objective.shape[1]\n    tri = ops.triu(ops.ones((n, n), dtype=win.dtype, device=objective.device), diagonal=1)\n    tri = tri.to(dtype=ops.bool)\n    win = win & tri[None, :, :]\n\n    b_idx, winner_idx, loser_idx = win.nonzero(as_tuple=True)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_tie_dedup', 'tie_eps': eps})\n"
}
